            aOrbiterJ = (aWandererC + RotL64(aCross, 57U)) + 0x8BE3391EF2B39E3BULL;
            aOrbiterA = (aWandererI + RotL64(aIngress, 43U)) + 0x0EF48B835A6BC7A1ULL;
            //
