            aOrbiterG = (aOrbiterG + aOrbiterJ) + 0xF288197F1B953ACCULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterG) ^ 0x142741D1ADB206B8ULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 17U)) & S_SALT1];
