            aWandererH = aWandererH ^ (((RotL64(aCross, 41U) + aOrbiterH) + RotL64(aOrbiterD, 57U)) + aTwistWandererUpdateSaltF[(((31U - aIndex) + 4U)) & S_SALT1]);
            aWandererE = aWandererE + (((RotL64(aScatter, 35U) + RotL64(aOrbiterJ, 12U)) + aOrbiterG) + RotL64(aCarry, 51U));
