            aOrbiterC = ((aWandererC + RotL64(aScatter, 35U)) + RotL64(aCarry, 5U)) + 0x920C5419645350A5ULL;
            aOrbiterJ = (aWandererE + RotL64(aIngress, 41U)) + 0x06EEA94F9284767FULL;
            aOrbiterI = ((aWandererI + RotL64(aPrevious, 47U)) + 0x959EE847B5457CDCULL) + aTwistOrbiterAssignSaltA[((aIndex + 16U)) & S_SALT1];
            aOrbiterB = (aWandererK + RotL64(aCross, 4U)) + 0x5D30EC45B8994EA0ULL;
            aOrbiterF = (((aWandererJ + RotL64(aPrevious, 21U)) + RotL64(aCarry, 53U)) + 0xB8C215AECD39C5DFULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterE = (aWandererA + RotL64(aIngress, 53U)) + 0x6524479C36AA43F2ULL;
            //
            aOrbiterK = (aOrbiterK + aOrbiterC) + 0x53A9E34FD26D1AB1ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterK) ^ 0x30A7D96F1C52C5D3ULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x59050ED241F2DE3FULL), 53U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterK) + 0xA589F66B905F2CDDULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0x8B6DA5B429C17E3CULL;
            aOrbiterB = RotL64((aOrbiterB * 0x4488AEAD1E3C5E63ULL), 19U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0x922F27F0A5536F92ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0x7BAE7982E233DA64ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x4CAA12A771AB4C91ULL), 29U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0x06CCFBA3E3CF578CULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterF) ^ 0xDD92D0F17A080F46ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xD1C8EE90E24816F3ULL), 39U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterJ) + 0x5CACDB32173F2A4AULL) + aTwistOrbiterUpdateSaltB[((aIndex + 3U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0x07CC5090735EDDE9ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x1881743714A413E3ULL), 47U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterB) + 0x030BD90940B472DFULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterC) ^ 0xA435AA6D68EEF3C2ULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x65538E0520F66CEFULL), 5U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterI) + 0x6A67BB30BA6A8DCCULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterE) ^ 0xF53ED0AF92B2E0FAULL;
            aOrbiterC = RotL64((aOrbiterC * 0x6739835929B4F02BULL), 13U);
