            aCross = (RotL64(aFireLaneC[((S_BLOCK1 - aIndex + 15282U)) & S_BLOCK1], 27U) ^ RotL64(aEarthLaneC[((S_BLOCK1 - aIndex + 13628U)) & S_BLOCK1], 52U));
