            //
            aScatter = (RotL64(aPrevious, 5U) + RotL64(aCross, 29U)) ^ (RotL64(aCarry, 41U) + RotL64(aIngress, 56U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
