            aOrbiterD = RotL64((aOrbiterD * 0x76DE440F93EC2367ULL), 27U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterA) + 0x6D262856FE3BBDD3ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterF) ^ 0x2CA2DFAE66F0FA9CULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xF80AF2F9F344282DULL), 37U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterB) + 0x0A74F462A97EDEBDULL;
