            aWandererA = aWandererA ^ (((RotL64(aCross, 41U) + aOrbiterF) + RotL64(aOrbiterK, 29U)) + aTwistWandererUpdateSaltA[((aIndex + 3U)) & S_SALT1]);
            aWandererK = aWandererK + (((RotL64(aPrevious, 3U) + RotL64(aOrbiterK, 57U)) + aOrbiterI) + RotL64(aCarry, 41U));
            aWandererF = aWandererF ^ (((RotL64(aScatter, 19U) + RotL64(aOrbiterB, 11U)) + aOrbiterE) + aTwistWandererUpdateSaltC[(((31U - aIndex) + 27U)) & S_SALT1]);
