            aOrbiterK = ((aWandererJ + RotL64(aScatter, 47U)) + 0xD16A5ED73F2CE128ULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterD = ((aWandererC + RotL64(aIngress, 57U)) + 0x519065979092031CULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 18U)) & S_SALT1];
            aOrbiterC = ((aWandererF + RotL64(aScatter, 39U)) + RotL64(aCarry, 43U)) + 0xA628E56EC8B981C0ULL;
