            //
            aOrbiterJ = ((aWandererC + RotL64(aScatter, 37U)) + RotL64(aCarry, 43U)) + 0xF5E785249E3CDCF6ULL;
            aOrbiterD = ((aWandererJ + RotL64(aIngress, 29U)) + RotL64(aCarry, 5U)) + 0xE63788C765DBC585ULL;
            aOrbiterF = (aWandererF + RotL64(aCross, 57U)) + 0x8C9B737280EA19D5ULL;
            aOrbiterK = (((aWandererH + RotL64(aPrevious, 13U)) + RotL64(aCarry, 29U)) + 0x5CC439017825A8F7ULL) + aTwistOrbiterAssignSaltF[((aIndex + 8U)) & S_SALT1];
            aOrbiterA = ((aWandererE + RotL64(aIngress, 48U)) + 0xE9686412E116EA3EULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterG = (aWandererG + RotL64(aCross, 21U)) + 0x3811A3D71363C0B7ULL;
            aOrbiterC = (aWandererB + RotL64(aPrevious, 3U)) + 0x9C06A3DE8DE3686FULL;
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0xE7F46FB2ADD0D619ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterJ) ^ 0x94F6B4C9BBBA8ED7ULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 3U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x8499F5308F0D1931ULL), 23U);
