            aOrbiterA = (aOrbiterA + aOrbiterJ) + 0x1ECC3AEB7E1365DBULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterA) ^ 0x18BAF365FA23E04AULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 5U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x53AB6BC86E62F7ADULL), 35U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterF) + 0xF4B6BE872235DD64ULL) + aTwistOrbiterUpdateSaltF[((aIndex + 10U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterG) ^ 0xFBB90E76A531AC5AULL;
            aOrbiterC = RotL64((aOrbiterC * 0xA56B18FBCF6B155FULL), 5U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterA) + 0xE3FADA34D68FEBC0ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterC) ^ 0x71A181FC7A887A18ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x0C06EDC31E7A1A45ULL), 41U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterC) + 0x10111C3D3AAD6A9DULL;
