            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0xC4988A2A409DB654ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0x5ED06E7E6140A1B8ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x8BEDEF99B976888BULL), 11U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterI) + 0x4D610D09456A279CULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 18U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterC) ^ 0xF6D7C2D3D763AA48ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x101B352A651E0571ULL), 35U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterE) + 0x5A6EF5C829ACFA71ULL) + aTwistOrbiterUpdateSaltC[((aIndex + 17U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0xD8A9CAA8E7A18272ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xBC2023513404542DULL), 47U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterF) + 0xC15A5FA463184396ULL) + aTwistOrbiterUpdateSaltE[((aIndex + 12U)) & S_SALT1];
