            aOrbiterJ = ((aWandererF + RotL64(aPrevious, 51U)) + 0x3AAF64DD6940BA9DULL) + aTwistOrbiterAssignSaltD[((aIndex + 4U)) & S_SALT1];
            aOrbiterE = (aWandererK + RotL64(aIngress, 11U)) + 0xD666F3F04511BAB3ULL;
            aOrbiterI = (aWandererH + RotL64(aCross, 29U)) + 0x29C315BB2109BCB5ULL;
            aOrbiterD = (aWandererC + RotL64(aPrevious, 41U)) + 0x90F0DF25A7C37BF5ULL;
