            aWandererJ = aWandererJ + (((RotL64(aIngress, 57U) + RotL64(aOrbiterF, 19U)) + aOrbiterK) + RotL64(aCarry, 39U));
            aWandererD = aWandererD ^ ((RotL64(aPrevious, 30U) + RotL64(aOrbiterD, 11U)) + aOrbiterF);
            aWandererB = aWandererB + (((RotL64(aScatter, 37U) + RotL64(aOrbiterH, 39U)) + aOrbiterI) + RotL64(aCarry, 29U));
