            //
            aOrbiterB = ((aWandererE + RotL64(aPrevious, 11U)) + RotL64(aCarry, 37U)) + 0x25041CC9A81523C4ULL;
            aOrbiterF = (((aWandererI + RotL64(aCross, 57U)) + RotL64(aCarry, 23U)) + 0xA1473530179783DFULL) + aTwistOrbiterAssignSaltE[((aIndex + 24U)) & S_SALT1];
            aOrbiterH = (aWandererD + RotL64(aIngress, 23U)) + 0xBE0309169DEA9605ULL;
