            aOrbiterD = (aWandererK + RotL64(aPrevious, 29U)) + 0x4595DB4AE5919DC6ULL;
            //
            aOrbiterB = ((aOrbiterB + aOrbiterF) + 0x5983B1BBB7A2F2BAULL) + aTwistOrbiterUpdateSaltA[((aIndex + 26U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x504CB6095D446F75ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x998B9C678433E5BBULL), 27U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterE) + 0x43DB89DD297D0220ULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterK) ^ 0xAD5885F891BB12FBULL;
            aOrbiterC = RotL64((aOrbiterC * 0xFDF6EF441A2F3CE9ULL), 39U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterA) + 0x2C41184B2E79AC64ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterC) ^ 0x8C204848F7AAF4EAULL) ^ aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x2CE305C943380EBFULL), 5U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x8FC38C4B12A0377AULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterE) ^ 0xBB34F998EF0EDF94ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x0B54B2BA6DF15DCBULL), 3U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterJ) + 0x937A8C05057BABE1ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterF) ^ 0x9E749F4BE06638ABULL;
