            aOrbiterH = ((aOrbiterH + aOrbiterK) + 0xFC3F17E946B75366ULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0x7F0203E6EA7360BCULL;
