    std::uint8_t *aIceLaneD = pWorkSpace->mIceLaneD;
    std::uint8_t *aKeyRowReadA = &(pWorkSpace->mKeyBoxA[H_KEY - 1][0]);
    std::uint64_t *aTwistOrbiterAssignSaltA = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterAssign.mSaltA;
    std::uint64_t *aTwistOrbiterAssignSaltB = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterAssign.mSaltB;
    std::uint64_t *aTwistOrbiterAssignSaltC = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterAssign.mSaltC;
    std::uint64_t *aTwistOrbiterAssignSaltD = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterAssign.mSaltD;
    std::uint64_t *aTwistOrbiterAssignSaltE = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterAssign.mSaltE;
    std::uint64_t *aTwistOrbiterAssignSaltF = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterAssign.mSaltF;
