            aWandererB = aWandererB + (((RotL64(aIngress, 13U) + RotL64(aOrbiterD, 39U)) + aOrbiterG) + aTwistWandererUpdateSaltB[((aIndex + 7U)) & S_SALT1]);
            aWandererH = aWandererH ^ ((RotL64(aScatter, 57U) + RotL64(aOrbiterK, 23U)) + aOrbiterC);
