            aWandererE = aWandererE ^ ((RotL64(aCross, 60U) + aOrbiterK) + RotL64(aOrbiterG, 13U));
            //
            aCarry = aCarry + (aWandererD ^ RotL64(aWandererH, 18U));
            aCarry = aCarry + (aWandererA ^ RotL64(aWandererG, 37U));
