            aIngress ^= (RotL64(aSoilLaneA[((aIndex + 1555U)) & S_BLOCK1], 19U) ^ RotL64(aPlasmaLaneC[((S_BLOCK1 - aIndex + 6008U)) & S_BLOCK1], 11U));
