            aCross = (RotL64(aPoisonLaneC[((S_BLOCK1 - aIndex + 6988U)) & S_BLOCK1], 21U) ^ RotL64(aEarthLaneC[((S_BLOCK1 - aIndex + 1016U)) & S_BLOCK1], 44U));
            aCross ^= (RotL64(aSoilLaneD[((S_BLOCK1 - aIndex + 6028U)) & S_BLOCK1], 57U) ^ RotL64(aWoodLaneB[((aIndex + 5586U)) & S_BLOCK1], 11U));
            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aPrevious, 27U) ^ RotL64(aCross, 6U)) ^ (RotL64(aIngress, 43U) + RotL64(aCarry, 57U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterH = ((aWandererD + RotL64(aCross, 13U)) + RotL64(aCarry, 41U)) + 0x89C7118A7AAACB9DULL;
            aOrbiterD = ((aWandererJ + RotL64(aIngress, 26U)) + 0xAD10774090EAC4D6ULL) + aKeyRotateOrbiterAssignSaltE[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterG = (aWandererE + RotL64(aScatter, 19U)) + 0xA2819567B9A6B2BFULL;
            aOrbiterB = ((aWandererC + RotL64(aPrevious, 37U)) + RotL64(aCarry, 53U)) + 0x64B5F013186211C5ULL;
            aOrbiterI = (((aWandererA + RotL64(aScatter, 53U)) + RotL64(aCarry, 5U)) + 0x02E922C678F4854DULL) + aKeyRotateOrbiterAssignSaltA[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterJ = (aWandererG + RotL64(aCross, 47U)) + 0xEDBDDA5433E83CDDULL;
            aOrbiterK = (aWandererF + RotL64(aIngress, 3U)) + 0xDFAA49713E6AA167ULL;
            //
            aOrbiterH = (aOrbiterH + aOrbiterD) + 0xF883DEAE12B439CBULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0xE29C3BBC35D10436ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xF6E6DE0BC8C6DD21ULL), 11U);
