            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0x9EC7C4BF2CAEDC93ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterJ) ^ 0x242C20250D656B89ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xD59BC77F48B69189ULL), 51U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterJ) + 0x7F60954FCC6A42D3ULL) + aKeyRotateOrbiterUpdateSaltA[((aIndex + 9U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterG) ^ 0x04F63596CC7958AEULL;
            aOrbiterI = RotL64((aOrbiterI * 0xE97C0F011CE67E81ULL), 5U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0x24EF0CC86D5073BCULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterK) ^ 0x940E54B61AA04715ULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x385E62BE56BF2E8BULL), 19U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterB) + 0x3379E042437BDB99ULL) + aKeyRotateOrbiterUpdateSaltF[((aIndex + 20U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0x3C45D35BF81BE733ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x2B5431DC1A3C2D69ULL), 39U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0x54949E2A428BD54CULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterI) ^ 0x10AB8F7BE74C41EBULL) ^ aKeyRotateOrbiterUpdateSaltD[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x8203A75A14DD25D1ULL), 57U);
            //
            aIngress = aOrbiterG ^ RotL64(aOrbiterJ, 37U);
            aIngress = aIngress + (RotL64(aOrbiterH, 4U) ^ aOrbiterD);
            aIngress = aIngress + (aOrbiterK ^ RotL64(aOrbiterI, 47U));
            aIngress = aIngress + RotL64(aOrbiterB, 19U);
