            aWandererF = aWandererF + ((RotL64(aCross, 11U) + aOrbiterD) + RotL64(aOrbiterK, 40U));
            aWandererC = aWandererC ^ (((RotL64(aIngress, 54U) + aOrbiterK) + RotL64(aOrbiterJ, 43U)) + aKeyRotateWandererUpdateSaltA[(((31U - aIndex) + 25U)) & S_SALT1]);
            aWandererH = aWandererH + ((RotL64(aScatter, 39U) + aOrbiterJ) + RotL64(aOrbiterC, 3U));
