            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aCross, 37U) + RotL64(aPrevious, 53U)) + (RotL64(aIngress, 21U) ^ RotL64(aCarry, 6U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterF = (aWandererG + RotL64(aPrevious, 3U)) + 0x33E554506545F581ULL;
            aOrbiterD = (aWandererC + RotL64(aScatter, 5U)) + 0x9D7126132E775038ULL;
            aOrbiterB = (aWandererI + RotL64(aIngress, 53U)) + 0x3566C5E63AE9E7A2ULL;
            aOrbiterA = (((aWandererA + RotL64(aCross, 23U)) + RotL64(aCarry, 27U)) + 0x18BCA09633870A50ULL) + aKeyRotateOrbiterAssignSaltB[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterH = ((aWandererK + RotL64(aIngress, 56U)) + 0x4DA39E6C616670EBULL) + aKeyRotateOrbiterAssignSaltE[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterJ = (aWandererD + RotL64(aScatter, 11U)) + 0xA51B811BE861621CULL;
            aOrbiterC = (aWandererE + RotL64(aPrevious, 41U)) + 0xCC8B41DB092264BCULL;
            aOrbiterK = (aWandererH + RotL64(aCross, 19U)) + 0x23B38733819EF263ULL;
            aOrbiterE = ((aWandererB + RotL64(aPrevious, 13U)) + RotL64(aCarry, 23U)) + 0x285A64821F645DD2ULL;
            aOrbiterI = ((aWandererJ + RotL64(aIngress, 60U)) + RotL64(aCarry, 5U)) + 0x69AEAC89095CCD8BULL;
            aOrbiterG = (aWandererF + RotL64(aCross, 29U)) + 0xE1AF8B0FCCB68F38ULL;
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0x222AAE056AAA3A1FULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0x37020BB3AC6EA237ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x8E39BB4CFC1D585DULL), 51U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterH) + 0x95B5172682B24040ULL) + aKeyRotateOrbiterUpdateSaltB[((aIndex + 15U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0x872AB78C9CA34F0EULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xAF4045430BF02B79ULL), 13U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterC) + 0xAED87ADB09E2B99FULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0x1D6D48F455E80866ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x144C6087CCCC9513ULL), 29U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterJ) + 0x884CB264279EEE08ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterK) ^ 0x92B3D8B0DC19C2F4ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x1D7A4BBBF51F8B2FULL), 47U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterI) + 0x9C12BE3BB58D3EB3ULL) + aKeyRotateOrbiterUpdateSaltE[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x7094D72DB13BE541ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x019A08B3D9DE2F73ULL), 53U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterB) + 0x87D4A7EE57F66493ULL) + aKeyRotateOrbiterUpdateSaltA[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0x436287F22A9B03F7ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x31211D76DA310579ULL), 43U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterG) + 0xE9146D4AA55AB33BULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterD) ^ 0xD6B4494078197C5AULL;
            aOrbiterI = RotL64((aOrbiterI * 0x5AA4267AE3263E09ULL), 35U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterK) + 0xCFB742D1CCDCC780ULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0xADFCF953CEDF4551ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x67F6AE60B66E6779ULL), 3U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterF) + 0xFA9F4A95D204866CULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterE) ^ 0x09ABD4E3780CB4AFULL;
            aOrbiterG = RotL64((aOrbiterG * 0x84FA24A867B2C0E5ULL), 37U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0x0BE5AB916899A8CFULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0x881779C3888F6793ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xA30408A50B4ECA2FULL), 39U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterE) + 0x15EB85167556C9D2ULL) + aKeyRotateOrbiterUpdateSaltF[((aIndex + 24U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterC) ^ 0xB43BEDBFAB18E7BCULL;
