            aWandererA = aWandererA + (((RotL64(aCross, 23U) + aOrbiterF) + RotL64(aOrbiterH, 5U)) + RotL64(aCarry, 53U));
            aWandererI = aWandererI ^ ((RotL64(aPrevious, 51U) + RotL64(aOrbiterC, 21U)) + aOrbiterJ);
            aWandererC = aWandererC + (((RotL64(aScatter, 5U) + aOrbiterI) + RotL64(aOrbiterK, 57U)) + RotL64(aCarry, 39U));
