            aWandererJ = aWandererJ + ((RotL64(aCross, 27U) + aOrbiterB) + RotL64(aOrbiterK, 23U));
            aWandererE = aWandererE ^ (((RotL64(aPrevious, 37U) + aOrbiterG) + RotL64(aOrbiterD, 37U)) + aKeyRotateWandererUpdateSaltB[((aIndex + 25U)) & S_SALT1]);
            aWandererF = aWandererF + (((RotL64(aScatter, 47U) + RotL64(aOrbiterC, 34U)) + aOrbiterD) + aKeyRotateWandererUpdateSaltD[(((31U - aIndex) + 18U)) & S_SALT1]);
            //
            aCarry = aCarry + (aWandererK ^ RotL64(aWandererH, 11U));
            aCarry = aCarry + (RotL64(aWandererJ, 30U) ^ aWandererI);
            aCarry = aCarry + (aWandererC ^ RotL64(aWandererB, 43U));
