            aOrbiterH = ((aOrbiterH + aOrbiterA) + 0xAFB34386AD5AEAE1ULL) + aKeyRotateOrbiterUpdateSaltC[((aIndex + 24U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0x94328456655F72A2ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xE53E9C138C142597ULL), 13U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterI) + 0xCAF614CF123DEC52ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterB) ^ 0x5A9A30A54E9A58E2ULL) ^ aKeyRotateOrbiterUpdateSaltE[((aIndex + 3U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x45CAD2885B38CE37ULL), 3U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterC) + 0x2B24E563DA6D6216ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0x42BF4823F51B0E44ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x8E6F557630E65BC1ULL), 35U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterB) + 0xD1D9726701391E6FULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterC) ^ 0x1CE2FC41A0E6F9C4ULL) ^ aKeyRotateOrbiterUpdateSaltD[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xC0B7EF38CAACEBC9ULL), 43U);
