            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0x5EC5F2CAA61D7E21ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterB) ^ 0xF1E40565EE0D98F7ULL) ^ aKeySpawnOrbiterUpdateSaltF[((aIndex + 5U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xBEEB6964979BC7BFULL), 47U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterE) + 0x5B46834CC2ED025AULL;
