            aOrbiterJ = RotL64((aOrbiterJ * 0x48A923750581F07DULL), 3U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0xA2EBD28BD17ACC14ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterJ) ^ 0x4FB018F5C055E933ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x8C4D4678BC4E5035ULL), 57U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0x14222CE9510ECEC1ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0x0279E131816962AFULL;
            aOrbiterH = RotL64((aOrbiterH * 0x305B6053A3BA7573ULL), 11U);
