            aOrbiterI = (aOrbiterI + aOrbiterH) + 0x6BC1014B9833A1B8ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterI) ^ 0xBB3AED0B46B53146ULL) ^ aKeySpawnOrbiterUpdateSaltB[((aIndex + 6U)) & S_SALT1];
