            aWandererJ = aWandererJ + (((RotL64(aIngress, 48U) + RotL64(aOrbiterH, 39U)) + aOrbiterA) + RotL64(aCarry, 19U));
            //
            aCarry = aCarry + (RotL64(aWandererJ, 23U) ^ aWandererK);
