            aIngress ^= (RotL64(aSpiritLaneC[((aIndex + 13645U)) & S_BLOCK1], 23U) ^ RotL64(aKineticLaneA[((aIndex + 9294U)) & S_BLOCK1], 6U));
            aIngress = TwistMix64::DiffuseC(aIngress);
