            aCross = (RotL64(aCelestialLaneA[((S_BLOCK1 - aIndex + 14464U)) & S_BLOCK1], 57U) ^ RotL64(aCelestialLaneD[((S_BLOCK1 - aIndex + 10400U)) & S_BLOCK1], 13U));
